items.command:
/bin/bash -lc "python3 - <<'PY'
import json
from pathlib import Path

source_path = Path('sales-input.json')
with source_path.open('r', encoding='utf-8') as source_file:
    data = json.load(source_file)

def collect_integers(value, found):
    if type(value) is int:
        found.append(value)
    elif isinstance(value, dict):
        for item in value.values():
            collect_integers(item, found)
    elif isinstance(value, list):
        for item in value:
            collect_integers(item, found)

integers = []
collect_integers(data, integers)
if not integers:
    raise ValueError('sales-input.json 中没有整数')

result = {'total': sum(integers), 'max': max(integers)}
serialized = json.dumps(result, ensure_ascii=False, separators=(',', ':'))
Path('analysis.json').write_text(serialized + '\\n', encoding='utf-8')
print(f'整数数量={len(integers)} total={result[\"total\"]} max={result[\"max\"]}')
print(f'原始顶层类型={type(data).__name__}')
PY"

